def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    my_def = sum(1 for a in my if a == 'D')
    opp_def = sum(1 for a in opp if a == 'D')
    last_me, last_opp = history[-1]

    if n == 99:
        return 'D'

    if n >= 3 and opp_def >= 2:
        if last_opp == 'C':
            return 'C'
        return 'D'

    if opp_def == 0:
        if my_def == 0:
            if n < 10:
                return 'C'
            elif n == 10:
                return 'D'
            elif n <= 15:
                return 'C'
            else:
                return 'D'
        else:
            if n <= 15:
                return 'C'
            else:
                return 'D'

    if opp_def >= 8 and opp_def * 2 > n:
        return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            return 'D'
        else:
            streak = 0
            for a in reversed(opp):
                if a == 'D':
                    streak += 1
                else:
                    break
            if streak >= 3:
                return 'D'
            if opp_def * 3 < n:
                return 'C'
            return 'D'
    else:
        if last_me == 'D':
            return 'C'
        return 'C'
